const {icons,boat}=window.designAssets;
const q=new URLSearchParams(location.search);
const state={direction:q.get('direction')||'a',page:q.get('page')||'overview',theme:q.get('theme')||'light',platform:q.get('platform')||'windows',scenario:q.get('state')||'ready',tab:'files',selectionTab:'projects',query:'',selected:'spice',settingsTab:'general',toast:'',progress:false,saved:false,reviewDirection:q.get('transfer')||'push',choices:{},reviewGroup:'all'};
const projects=[
{id:'spice',name:'Spice Route',chats:8,history:72,full:860,folder:'Code / Spice Route'},
{id:'atlas',name:'Atlas',chats:4,history:28,full:1480,folder:'Projects / Atlas'},
{id:'travel',name:'Travel notes',chats:3,history:19,full:24,folder:'Documents / Travel'},
{id:'notepad',name:'Notepad',chats:2,history:16,full:430,folder:'Code / Notepad'},
{id:'flights',name:'Flight tracker',chats:2,history:12,full:220,folder:'Code / Flights'},
{id:'site',name:'Personal website',chats:2,history:10,full:390,folder:'Code / Website'},
{id:'recipes',name:'Recipe book',chats:1,history:9,full:54,folder:'Projects / Recipes'},
{id:'study',name:'Study notes',chats:1,history:8,full:38,folder:'Documents / Study'},
{id:'budget',name:'Budget planner',chats:1,history:7,full:128,folder:'Code / Budget'},
{id:'garden',name:'Garden journal',chats:1,history:6,full:16,folder:'Documents / Garden'},
{id:'reading',name:'Reading list',chats:1,history:4,full:21,folder:'Documents / Reading'},
{id:'weekend',name:'Weekend plans',chats:1,history:4,full:12,folder:'Documents / Weekend'},
].map(p=>({...p,mode:'history'}));
const changes=[
{name:'Refine the settings page',project:'Spice Route',id:'spice',size:28,kind:'Updated',time:'Today, 10:12 AM'},
{name:'Plan the next release',project:'Spice Route',id:'spice',size:18,kind:'Updated',time:'Today, 10:06 AM'},
{name:'Pack for Kyoto',project:'Travel notes',id:'travel',size:6,kind:'Updated',time:'Today, 9:58 AM'}
];
const chats=[{title:'Plan a long weekend',size:4},{title:'Compare camera lenses',size:3},{title:'Draft a thank-you note',size:2},{title:'Organize reading notes',size:1},...Array.from({length:8},(_,i)=>({title:['Learn a keyboard shortcut','Sketch a dinner menu','Understand a SQL query','Review a travel checklist','Summarize meeting notes','Format a spreadsheet','Plan a study session','Tidy up a presentation'][i],size:.25}))].map((c,i)=>({...c,id:'chat-'+i,included:true}));
const projectChats=projects.flatMap(p=>Array.from({length:p.chats},(_,i)=>({id:p.id+'-'+i,project:p.id,included:true,title:((p.id==='spice'?['Refine the settings page','Plan the next release','Simplify the review flow','Investigate a startup issue','Polish the folder controls','Check a restore','Improve diagnostics','Prepare a Mac build']:p.id==='atlas'?['Build the search view','Fix keyboard shortcuts','Organize navigation','Refine the empty state']:p.id==='travel'?['Pack for Kyoto','Plan a day in Osaka','Compare train routes']:['Plan the next steps','Review the first draft'])[i]),size:p.id==='spice'?(i===0?28:i===1?18:26/6):p.id==='travel'?[6,7,6][i]:p.history/p.chats})));
const hasIncoming=()=>['incoming','blocked'].includes(state.scenario);
const latestTime=()=>hasIncoming()?'10:18 AM':'9:42 AM';
const latestCode=()=>hasIncoming()?'8C31':'4B7A';
const descriptions={
a:['A · Focus','One clear next action. Details stay one click away.'],
b:['B · Side by side','See this device and the latest cloud handoff together.'],
c:['C · Workbench','Select, inspect, and review in a compact workspace.']
};
const icon=n=>icons[n]||icons.circle;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,attrs='',glyph='',cls='')=>`<button class="${cls}" ${attrs}>${glyph?icon(glyph):''}${label}</button>`;
const badge=(label,tone='',glyph='')=>`<span class="badge ${tone}">${glyph?icon(glyph):''}${label}</span>`;
const glyph=n=>`<span class="glyph">${icon(n)}</span>`;
const selectedProjects=()=>projects.filter(p=>p.mode!=='excluded');
const chatCount=()=>selectedProjects().reduce((v,p)=>v+projectChats.filter(c=>c.project===p.id&&c.included).length,0)+chats.filter(c=>c.included).length;
const historyBytes=p=>projectChats.filter(c=>c.project===p.id&&c.included).reduce((n,c)=>n+c.size,0);
const projectBytes=p=>p.mode==='excluded'?0:historyBytes(p)+(p.mode==='full'?p.full-p.history:0);
const bytes=()=>selectedProjects().reduce((v,p)=>v+projectBytes(p),0)+chats.filter(c=>c.included).reduce((v,c)=>v+c.size,0);
const size=n=>n>=1000?(n/1000).toFixed(1)+' GB':(Number.isInteger(n)?n:n.toFixed(1))+' MB';
const scope=()=>projects.some(p=>p.mode==='full')?'Chats and project files':'Chat history only';
const modeLabel=v=>({history:'Chat history only',full:'Full project',excluded:'Excluded'}[v]);
const mode=p=>button(`${modeLabel(p.mode)}${icon('chevronDown')}`,`data-menu="mode:${p.id}" aria-haspopup="menu" aria-expanded="false" aria-label="Sync mode for ${esc(p.name)}"`,'','mode-trigger');
const folder=(text,id)=>button(`<span>${esc(text)}</span>${icon('ellipsis')}`,`data-menu="folder:${id}" aria-haspopup="menu" aria-expanded="false" aria-label="Change folder for ${esc(text)}"`,'folder','folder-link');
const note=(text,n='info')=>`<div class="detail-note">${icon(n)}<span>${text}</span></div>`;
const toast=()=>state.toast?`<span role="status" class="toast">${icon('check')}${esc(state.toast)}</span>`:'';
const actionButtons=()=>`<div class="actions">${button('Push','data-action="review-push"','arrowUp','primary')}${button('Pull','data-action="review-pull"','arrowDown')}</div>`;
const nextAction=()=>['incoming','blocked'].includes(state.scenario)?'Pull':'Push';
const header=(title,subtitle='',right='')=>`<header class="page-head"><div><h1>${title}</h1>${subtitle?`<div class="subtitle">${subtitle}</div>`:''}</div><div class="actions">${toast()}${right||button('','data-action="refresh" aria-label="Refresh" title="Refresh"','refresh','quiet icon')}</div></header>`;
function titlebar(){return `<div class="titlebar">${state.platform==='mac'?'<div class="traffic" aria-hidden="true"><span></span><span></span><span></span></div>':''}<span class="app-title"><img src="${boat}" alt="">Spice Route</span>${state.platform==='mac'?'':`<span class="window-controls" aria-hidden="true">${icon('minus')}${icon('square')}${icon('x')}</span>`}</div>`;}
function sidebar(){return `<aside class="sidebar">${button('','data-action="navigation-note" aria-label="Navigation menu"','menu','quiet icon')}<nav aria-label="Main navigation">${[['overview','Overview','home'],['selection','What to sync','folder'],['recovery','Recovery','history']].map(([id,label,i])=>button(label,`data-page="${id}" ${state.page===id||id==='overview'&&state.page==='review'?'aria-current="page"':''}`,i,'nav-item '+(state.page===id||id==='overview'&&state.page==='review'?'current':''))).join('')}</nav><div class="sidebar-end">${button('Settings','data-page="settings" '+(state.page==='settings'?'aria-current="page"':''),'settings','nav-item '+(state.page==='settings'?'current':''))}<div class="sidebar-device">${icon(state.platform==='mac'?'laptop':'monitor')}<span><strong>${'Work PC'}</strong>This device</span></div></div></aside>`;}
function latest(){return `<div class="compact-latest"><div><strong>Today, ${latestTime()}</strong><p>MacBook Pro · Sep 22 · ${latestCode()}</p></div>${button('Pull','data-action="review-pull"','arrowDown')}</div>`;}
function readyStatus(){if(state.scenario==='blocked')return `<div class="inline-warning">${icon('alert')}<div><strong>Two choices before pulling</strong><p>Choose a chat version and a local project folder before restoring.</p>${button('Review choices','data-action="review-pull"','','link')}</div></div>`;return '';}
function recent(){
const rows=hasIncoming()?[
['Today, 10:18 AM','From MacBook Pro','Not pulled on this device','cloud'],
['Today, 9:47 AM','Previous pull on Work PC','Received and verified','download'],
['Yesterday, 6:18 PM','Pushed from Work PC','Saved to sync folder','upload']
]:[['Today, 9:47 AM','Pulled on Work PC','Received and verified','download'],['Today, 9:42 AM','From MacBook Pro','Visible in sync folder','cloud'],['Yesterday, 6:18 PM','Pushed from Work PC','Saved to sync folder','upload']];
return `<section class="recent"><div class="section-title"><h2>Recent handoffs</h2>${button('View all','data-page="recovery"','','link')}</div>${rows.map(([time,who,what,i])=>`<div class="recent-row">${icon(i)}<span><strong>${time}</strong><small>${who}</small></span><span class="muted">${what}</span><span>${button('','data-page="recovery" aria-label="View handoff details"','chevronRight','quiet icon')}</span></div>`).join('')}</section>`;
}
function scopeRows(){return `<section class="scope-rows"><div class="section-title"><h2>In your next handoff</h2>${button('Edit selection','data-page="selection"','','link')}</div><div class="scope-row">${glyph('message')}<div><strong>${chatCount()} chats</strong><p>Project chats and projectless chats</p></div><span class="num size">${size(bytes())}</span></div><div class="scope-row">${glyph('folder')}<div><strong>${selectedProjects().length} projects</strong><p>${scope()}. ${scope()==='Chat history only'?'Project files stay on this computer.':'Selected project files are included.'}</p></div></div></section>`;}
function focusOverview(){return header('Overview')+`<div class="body"><div class="focus-layout">${readyStatus()}<section class="hero-focus"><div class="focus-device">${icon('monitor')}<span>${'Work PC'}</span>${badge(state.scenario==='blocked'?'Review needed':state.scenario==='incoming'?'New handoff available':'Ready to hand off',state.scenario==='blocked'?'warn':state.scenario==='incoming'?'':'good',state.scenario==='incoming'?'download':'check')}</div><h2>${state.scenario==='blocked'?'Review before you restore.':state.scenario==='incoming'?'Your next handoff is here.':'Ready for your next device.'}</h2><p>${state.scenario==='incoming'?'A handoff from MacBook Pro is visible in your sync folder. Review it before restoring.':'Push the chats you want to continue on your next computer.'}</p><div class="focus-actions">${button(nextAction(),`data-action="review-${nextAction().toLowerCase()}"`,nextAction()==='Push'?'arrowUp':'arrowDown','primary')}<span class="secondary">You’ll review changes first.</span></div></section>${scopeRows()}<section class="focus-bottom"><div class="section-title"><h2>Latest in sync folder</h2><span class="row secondary">${icon('cloud')}OneDrive</span></div>${latest()}<div style="margin-top:14px">${badge(state.scenario==='ready'?'Pulled on this device at 9:47 AM':'Not pulled on this device',state.scenario==='ready'?'good':'',state.scenario==='ready'?'check':'download')}</div></section><div style="margin-top:19px">${note('Your drive app handles delivery. Match the handoff on the other device.')}</div></div></div>`;}
function balanceOverview(){return header('Overview')+`<div class="body">${readyStatus()}<div class="alignment">${icon('check')}<span>${state.scenario==='blocked'?'Two choices are needed before pulling.':state.scenario==='incoming'?'A newer handoff is visible. Pull to review it.':'This device has the latest visible handoff.'}</span></div><section class="pair"><div class="pair-pane"><div class="pair-label">${icon('monitor')}This device</div><h2>${'Work PC'}</h2><p class="muted">Choose what goes to your next computer.</p><div class="pair-facts"><div><span>Selected chats</span><strong>${chatCount()}</strong></div><div><span>Projects</span><strong>${selectedProjects().length} · ${scope().toLowerCase()}</strong></div><div><span>Selected content</span><strong class="num">${size(bytes())}</strong></div></div><div class="pair-action">${button('Push','data-action="review-push"','arrowUp','primary')}${button('Edit selection','data-page="selection"','','link')}</div></div><div class="pair-pane"><div class="pair-label">${icon('cloud')}OneDrive sync folder</div><h2>Today, ${latestTime()}</h2><p class="muted">From MacBook Pro · latest visible handoff</p><div class="pair-facts"><div><span>Handoff</span><strong>Sep 22 · ${latestCode()}</strong></div><div><span>Contents</span><strong>39 chats · 12 projects</strong></div><div><span>On this device</span>${hasIncoming()?'<span class="muted">Not yet pulled</span>':'<strong class="pilltext">'+icon('check')+'Received and verified</strong>'}</div></div><div class="pair-action">${button('Pull','data-action="review-pull"','arrowDown')}${button('Details','data-action="handoff-details"','','link')}</div></div></section>${recent()}<div style="margin-top:21px">${note('Your drive app handles delivery. A visible handoff may still be downloading.')}</div></div>`;}
function projectTable(){const rows=projects.filter(p=>p.name.toLowerCase().includes(state.query.toLowerCase()));return `<table class="data-table"><colgroup><col style="width:51%"><col style="width:33%"><col style="width:16%"></colgroup><thead><tr><th>Project</th><th>Sync</th><th class="size">Size</th></tr></thead><tbody>${rows.map(p=>`<tr data-project="${p.id}" class="${state.selected===p.id?'selected':''}" aria-selected="${state.selected===p.id}"><td><span class="name">${icon('folder')}${button(esc(p.name),`data-project="${p.id}"`)}</span></td><td><span class="secondary">${modeLabel(p.mode)}</span></td><td class="size">${p.mode==='excluded'?'0 B':size(projectBytes(p))}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">No projects match your search.</div>':''}`;}
function inspector(){const p=projects.find(p=>p.id===state.selected)||projects[0];return `<aside class="inspector" aria-label="Project details">${glyph('folder')}<h2>${esc(p.name)}</h2><p>${p.chats} ${p.chats===1?'chat':'chats'}</p><div class="inspector-section"><h3>Include in handoff</h3>${mode(p)}<div class="definition"><span>Selected content</span><strong class="num">${p.mode==='excluded'?'0 B':size(projectBytes(p))}</strong></div></div><div class="inspector-section"><h3>Folder on this device</h3>${folder(p.folder,p.id)}<p style="margin-top:9px">Changing this path does not move files.</p></div>${note(p.mode==='excluded'?'This project is excluded from future handoffs. Its local files stay here.':p.mode==='full'?'Code, Git history, and selected working files are included.':'Chat history only includes chats and the project listing. Project files stay here.','info')}</aside>`;}
function workbenchOverview(){return header('Overview','',actionButtons())+`<div class="body workbench-overview">${readyStatus()}<div class="context-strip">${icon('cloud')}<span>OneDrive · latest visible: Today, ${latestTime()} · MacBook Pro</span>${button('Details','data-action="handoff-details"','','link')}</div><div class="toolbar"><div class="selection-summary"><strong>${chatCount()} chats</strong><span>${selectedProjects().length} projects</span><span class="num">${size(bytes())} selected</span></div>${search()}</div><div class="workbench"><div class="workbench-table">${projectTable()}</div>${inspector()}</div></div><footer class="page-footer"><span class="secondary">${hasIncoming()?'Previous pull verified at 9:47 AM. New handoff not yet pulled.':'Last pull verified at 9:47 AM.'}</span>${button('Edit all sync choices','data-page="selection"','','link')}</footer>`;}
function search(label='Find a project'){return `<label class="search">${icon('search')}<input aria-label="${label}" placeholder="${label}" value="${esc(state.query)}" id="search-field" autocomplete="off"></label>`;}
function selection(){const tabs=`<div class="tabs" role="tablist" aria-label="Content type">${[['projects','Projects',12],['project-chats','Project chats',27],['chats','Projectless chats',12]].map(([id,name,n])=>button(`${name} <span class="count">${n}</span>`,`data-selection-tab="${id}" role="tab" aria-selected="${state.selectionTab===id}"`)).join('')}</div>`;let body='';
if(state.selectionTab==='project-chats')body=`<p class="selection-heading">Exclude individual chats without changing the project’s file selection.</p><div class="project-list">${projectChats.filter(c=>c.title.toLowerCase().includes(state.query.toLowerCase())).map(c=>`<label class="project-item" style="grid-template-columns:20px 1fr 80px"><input type="checkbox" data-project-chat="${c.id}" ${c.included?'checked':''}><span class="identity"><strong>${esc(c.title)}</strong><span class="secondary">${projects.find(p=>p.id===c.project).name}</span></span><span class="num small" style="text-align:right">${size(c.size)}</span></label>`).join('')}</div>`;
else if(state.selectionTab==='chats')body=`<p class="selection-heading">Include the chats you want to take with you. Archived chats are included.</p><div class="project-list">${chats.filter(c=>c.title.toLowerCase().includes(state.query.toLowerCase())).map(c=>`<label class="project-item" style="grid-template-columns:20px 1fr 80px"><input type="checkbox" data-chat="${c.id}" ${c.included?'checked':''}><span class="identity"><strong>${esc(c.title)}</strong><span class="secondary">Projectless chat</span></span><span class="num small" style="text-align:right">${c.size<1?'250 KB':size(c.size)}</span></label>`).join('')}</div>`;
else if(state.direction==='c')body=`<div class="workbench"><div class="workbench-table">${projectTable()}</div>${inspector()}</div>`;
else body=`${state.direction==='b'?'<div class="project-column-head"><span></span><span>Project</span><span>Folder on this device</span><span>Sync</span></div>':''}<div class="project-list">${projects.filter(p=>p.name.toLowerCase().includes(state.query.toLowerCase())).map(p=>`<div class="project-item">${icon('folder')}<div class="identity"><strong>${esc(p.name)}</strong><div class="project-sub"><span>${p.chats} ${p.chats===1?'chat':'chats'} · ${p.mode==='excluded'?'0 B':size(projectBytes(p))}</span>${state.direction==='b'?'':folder(p.folder,p.id)}</div></div>${state.direction==='b'?folder(p.folder,p.id):''}${mode(p)}</div>`).join('')}</div>`;
return header('What to sync',`${chatCount()} chats · ${selectedProjects().length} projects · ${size(bytes())} selected`,button('Defaults','data-action="defaults"','','quiet'))+`<div class="body ${state.direction==='c'?'workbench-overview':''}">${tabs}<div class="toolbar">${search(state.selectionTab!=='projects'?'Find a chat':'Find a project')}<span class="secondary">Shared across devices</span></div>${body}</div><footer class="page-footer"><span class="secondary">Project folders are specific to this device.</span>${button('Save choices','data-action="save-choices"','','primary')}</footer>`;}
const activeChanges=()=>[
...changes.filter((c,i)=>projects.find(p=>p.id===c.id).mode!=='excluded'&&projectChats.find(t=>t.id===(i===2?'travel-0':'spice-'+i)).included).map(c=>({...c,type:'chat'})),
...selectedProjects().filter(p=>p.mode==='full').map(p=>({name:'Project files and Git history',project:p.name,id:p.id,size:p.full-p.history,kind:'New',type:'files'}))
];
const otherChats=()=>chatCount()-activeChanges().filter(c=>c.type==='chat').length;
const fileScope=()=>{const n=selectedProjects().filter(p=>p.mode==='full').length;return n?n+' full '+(n===1?'project includes':'projects include')+' code and Git history.':'Project working files are excluded.';};
const changeRows=()=>activeChanges().filter(c=>(state.reviewGroup==='all'||c.id===state.reviewGroup)&&(!state.query||[c.name,c.project].join(' ').toLowerCase().includes(state.query.toLowerCase()))).sort((a,b)=>(state.sortAscending?1:-1)*(a.size-b.size));
function filesTable(){return `<div class="file-view"><div class="toolbar">${search('Find a chat or file')}${button(state.sortAscending?'Smallest first':'Largest first','data-action="sort"','chevronDown','quiet')}</div><div class="file-scroll"><table class="data-table"><colgroup><col style="width:66%"><col style="width:18%"><col style="width:16%"></colgroup><thead><tr><th>Name</th><th>Change</th><th class="size">Size</th></tr></thead><tbody>${changeRows().map(c=>`<tr><td><span class="name">${icon(c.type==='files'?'file':'message')}<span>${esc(c.name)}</span></span><span class="secondary">${c.project}</span></td><td><span class="secondary">${c.kind}</span></td><td class="size">${size(c.size)}</td></tr>`).join('')}</tbody></table>${!changeRows().length?'<div class="empty">No changes match this view.</div>':''}</div>${note(otherChats()+' other selected chats are included. Existing content is reused.')}</div>`;}
function groupedFiles(){const groups=[...new Set(activeChanges().map(c=>c.id))];return `<div class="grouped-changes">${groups.map(id=>{const p=projects.find(p=>p.id===id),items=activeChanges().filter(c=>c.id===id);return `<details class="change-group" open><summary>${icon('folder')}<strong>${p.name}<small>${items.length} ${items.length===1?'change':'changes'}</small></strong><span class="num">${size(items.reduce((v,c)=>v+c.size,0))}</span>${icon('chevronDown')}</summary>${items.map(c=>`<div class="file-row"><div><strong>${c.name}</strong><div class="secondary">${c.type==='files'?'Project files':'Project chat'}</div></div><span class="badge">${c.kind}</span><span class="num">${size(c.size)}</span></div>`).join('')}</details>`;}).join('')}<div style="margin-top:22px">${note(otherChats()+' other selected chats are included. Existing content is reused.')}</div></div>`;}
function attention(){return `<div class="attention"><p class="attention-intro">Choose a version for each item. Your other chats are unaffected.</p><div class="attention-item">${icon('alert')}<div><h3>Refine the settings page</h3><p>This chat changed on both computers.</p><div class="choice-pair">${['local','incoming'].map(v=>button(`<strong>${icon(v==='local'?'monitor':'laptop')}${v==='local'?'Keep this device':'Use incoming'}</strong><small>${v==='local'?'Work PC · Today, 10:12 AM · 28 MB':'MacBook Pro · Today, 10:16 AM · 29 MB'}</small>`,`data-choice="${v}" aria-pressed="${state.choices.chat===v}"`)).join('')}</div></div></div><div class="attention-item">${icon('folder')}<div><h3>Choose a folder for Atlas</h3><p>This project has no folder on this device. Chat history only needs an empty local folder.</p><div style="margin-top:12px">${state.choices.folder?badge('Folder selected','good','check'):button('Choose folder','data-action="map-folder"','folder')}</div></div></div></div>`;}
function notes(){return `<div class="notes-list">${[['folder','What travels',fileScope()+' Excluded projects and chats stay on this computer.'],['cloud','Cloud delivery',state.reviewDirection==='pull'?'Pull verifies the handoff visible in your sync folder before restoring it. A newer remote handoff may still be arriving.':'Spice Route writes the handoff to OneDrive’s local folder. It cannot confirm arrival on another computer.'],['shield','Restoration is checked','Pull verifies the required content and keeps a local restore point before changing data.'],['monitor','Codex closes before transfer','If Codex is running, Spice Route requests a graceful exit. Transfer waits until all Codex writers have stopped.']].map(([i,t,b])=>`<div class="note-row">${icon(i)}<div><h3>${t}</h3><p>${b}</p></div></div>`).join('')}</div>`;}
function review(){if(state.progress||state.scenario==='progress')return progress();if(state.saved)return success();const needs=state.scenario==='blocked';const unresolved=(state.choices.chat?0:1)+(state.choices.folder?0:1);let content=state.tab==='attention'?(needs?attention():`<div class="empty">${glyph('check')}<h2 style="margin:12px 0 6px">No decisions needed</h2><p>Review the files, then ${state.reviewDirection==='push'?'Push':'Pull'} when you’re ready.</p></div>`):state.tab==='notes'?notes():state.direction==='a'?groupedFiles():`<div class="review-workspace">${state.direction==='c'?`<aside class="review-projects" aria-label="Filter changes by project">${[['all','All changes',size(activeChanges().reduce((n,c)=>n+c.size,0))],...[...new Set(activeChanges().map(c=>c.id))].map(id=>[id,projects.find(p=>p.id===id).name,size(activeChanges().filter(c=>c.id===id).reduce((n,c)=>n+c.size,0))])].map(([id,name,size])=>button(`<span>${name}<small>${size}</small></span>`,`data-group="${id}"`,'',''+(state.reviewGroup===id?'selected':''))).join('')}</aside>`:''}${filesTable()}${state.direction==='b'?`<aside class="review-summary"><h3>This handoff</h3><div class="definition"><span>Chats</span><strong>${chatCount()}</strong></div><div class="definition"><span>Project listings</span><strong>${selectedProjects().length}</strong></div><div class="definition"><span>Selected content</span><strong>${size(bytes())}</strong></div><div class="definition"><span>Changes</span><strong>${activeChanges().length}</strong></div>${note(fileScope(),'folder')}</aside>`:''}</div>`;
return header('Review '+state.reviewDirection,`${activeChanges().length} changes · 0 deletions · ${size(bytes())} selected`,button('','data-action="refresh" aria-label="Refresh review" title="Refresh review"','refresh','quiet icon'))+`<div class="review-body"><div class="tabs" role="tablist" aria-label="Review sections">${[['files','Changes',activeChanges().length],['attention','Needs attention',needs?unresolved:0],['notes','Details',null]].map(([id,name,n])=>button(`${name}${n!==null?` <span class="count">${n}</span>`:''}`,`role="tab" data-tab="${id}" aria-selected="${state.tab===id}"`)).join('')}</div>${content}</div><footer class="page-footer"><span class="secondary">${needs&&unresolved?`${unresolved} decisions to make before ${state.reviewDirection}.`:'Codex will close before the transfer starts.'}</span><div class="actions">${button('Cancel','data-page="overview"')}${button(state.reviewDirection==='push'?'Push':'Pull',`data-action="execute" ${needs&&unresolved?'disabled':''}`,state.reviewDirection==='push'?'arrowUp':'arrowDown','primary')}</div></footer>`;}
function progress(){const pull=state.reviewDirection==='pull';const steps=pull?[['check','Codex closed','complete'],['check','Handoff verified','complete'],['download','Restoring selected content','current'],['circle','Verify restored data','']]:[['check','Codex closed','complete'],['check','Selected content captured','complete'],['upload','Saving changed content','current'],['circle','Publish completed handoff','']];return header(pull?'Pulling handoff':'Pushing this device','',badge('In progress'))+`<div class="body"><div class="progress-section"><h2>${pull?'Restoring your handoff':'Saving changed content'}</h2><p>${pull?'Applying the verified handoff to this device.':'Preparing the handoff in your OneDrive folder.'}</p><div class="progressbar" role="progressbar" aria-label="${pull?'Restoring content':'Saving changed content'}"><span></span></div>${steps.map(([i,t,c])=>`<div class="step-row ${c}">${icon(i)}${t}</div>`).join('')}${note(pull?'A local restore point is kept before files change.':'Keep your drive app running after this step so it can deliver the handoff.')}</div></div><footer class="page-footer"><span class="secondary">Illustrative progress. No transfer is running.</span><div class="actions">${button('Cancel','data-action="cancel-progress"')}${button('Show completion','data-action="complete"','','primary')}</div></footer>`;}
function success(){const pull=state.reviewDirection==='pull';return header(pull?'Handoff restored':'Handoff saved')+`<div class="body"><div class="focus-layout"><section class="success-panel">${badge(pull?'Received and verified':'Saved to sync folder','good','check')}<h2>${pull?'Your handoff is restored.':'Ready for your drive app.'}</h2><p>${pull?'Selected chats and project listings are restored on this device.':'Keep OneDrive running to deliver this handoff.'}</p><div class="row"><strong>${pull?'From MacBook Pro · Today, '+latestTime():'Today, 10:24 AM · Work PC'}</strong>${button(pull?'Sep 22 · '+latestCode():'Sep 22 · 8C31','data-action="copy-id"','copy','quiet')}</div></section>${note(pull?'Open Codex when you’re ready to continue. If something is missing, inspect the last pull in Recovery.':'On your next computer, find this handoff and Pull. Completion here does not confirm cloud delivery.',pull?'shield':'cloud')}<div class="actions" style="margin-top:26px">${button('Back to overview','data-page="overview"','','primary')}${pull?button('Inspect last pull','data-action="diagnostics"','','quiet'):''}</div></div></div>`;}
function settingRow(i,title,description,control){return `<div class="setting-row">${icon(i)}<div class="setting-label"><strong>${title}</strong><p>${description}</p></div><div class="setting-control">${control}</div></div>`;}
function settings(){const general=`<section class="settings-section" data-section="general"><h2>This device</h2>${settingRow('monitor','Device name','Shown beside your handoffs.','<input aria-label="Device name" value="Work PC" data-setting="device">')}${settingRow('palette','Appearance','Match your desktop or choose a theme.',`<select aria-label="Appearance" id="appearance"><option value="system">System</option><option value="light" ${state.theme==='light'?'selected':''}>Light</option><option value="dark" ${state.theme==='dark'?'selected':''}>Dark</option></select>`)}</section>`;
const cloud=`<section class="settings-section" data-section="cloud"><h2>Cloud drive</h2>${settingRow('cloud','Provider','Your drive app handles sign-in and delivery.',`<select aria-label="Cloud provider" data-setting="provider"><option>OneDrive</option><option>Google Drive</option><option>iCloud Drive</option></select>`)}${settingRow('folder','Sync folder','Completed handoffs are saved here.',folder('OneDrive / Spice Route','cloud'))}</section>`;
const folders=`<section class="settings-section" data-section="folders"><h2>Local folders</h2>${settingRow('database','Codex history','The .codex folder with databases and transcripts.',folder('Codex / .codex','history'))}${settingRow('folder','Chat workspaces','Working files for projectless chats.',folder('Codex / Sessions','workspaces'))}${settingRow('folders','Project folders','Each project has its own local path.',button('Manage folders','data-page="selection"','chevronRight','link'))}</section>`;
const advanced=`<section class="settings-section" data-section="advanced"><h2>Maintenance</h2>${settingRow('shield','Compatibility','This database format is supported.',button('Details','data-action="diagnostics"','chevronRight','quiet'))}${settingRow('hardDrive','Cloud storage','684 MB across retained handoffs.',button('Manage','data-action="storage"','chevronRight','quiet'))}${settingRow('help','Diagnostics','Inspect startup and restoration reports.',button('View reports','data-action="diagnostics"','chevronRight','quiet'))}</section>`;
const all={general,cloud,folders,advanced};
return header('Settings','Changes apply to this device.')+`<div class="body">${state.direction==='c'?`<div class="settings-two"><nav class="settings-categories" aria-label="Settings category">${[['general','General'],['cloud','Cloud drive'],['folders','Local folders'],['advanced','Maintenance']].map(([id,label])=>button(label,`data-settings-tab="${id}"`,'',state.settingsTab===id?'active':'')).join('')}</nav><div class="settings-sections">${all[state.settingsTab]}</div></div>`:`<div class="settings-sections">${state.direction==='a'?'<div class="settings-folds"><details open><summary>Cloud drive</summary>'+cloud+'</details><details><summary>Local folders</summary>'+folders+'</details><details><summary>This device</summary>'+general+'</details></div>':general+cloud+folders}<details style="margin-top:25px"><summary style="cursor:pointer;padding:12px 0;font-size:13px">Maintenance and diagnostics</summary>${advanced}</details></div>`}</div><footer class="page-footer"><span class="secondary">Folder changes take effect on your next handoff.</span>${button('Save settings','data-action="save-settings"','','primary')}</footer>`;}
function recovery(){return header('Recovery','Restore points stay on this device.',button('Diagnostics','data-action="diagnostics"','help','quiet'))+`<div class="body"><div class="split-recovery"><div class="recovery-list"><div class="section-title"><h2>Local restore points</h2></div>${[['Today, 9:47 AM','Before pulling from MacBook Pro','214 MB'],['Yesterday, 5:52 PM','Before pulling from MacBook Pro','201 MB'],['Sep 20, 11:06 AM','Before pulling from Travel laptop','198 MB']].map(([date,desc,n])=>`<div class="recent-row">${icon('history')}<span><strong>${date}</strong><small>${desc}</small></span><span class="muted">${n}</span>${button('Review','data-action="restore-point"','','quiet')}</div>`).join('')}</div><aside><h2 style="margin-bottom:12px">Something missing?</h2><p class="secondary">Check the folders, chats, and project listings restored by your last Pull.</p><div style="margin-top:14px;margin-bottom:18px">${button('Inspect last pull','data-action="diagnostics"','search')}</div>${note('Keep the latest 10 successful restore points.','shield')}</aside></div></div>`;}
function render(){
document.documentElement.dataset.theme=state.theme;
document.documentElement.classList.toggle('capture',q.has('capture'));
const app=document.querySelector('#app');app.dataset.direction=state.direction;app.dataset.platform=state.platform;
const view=state.page==='overview'?(state.scenario==='progress'?progress():({a:focusOverview,b:balanceOverview,c:workbenchOverview}[state.direction])()):state.page==='selection'?selection():state.page==='review'?review():state.page==='settings'?settings():recovery();
app.innerHTML=titlebar()+`<div class="window-body">${sidebar()}<main class="main" aria-label="${state.page}">${view}</main></div><div class="statusbar"><span>${icon('cloud')}OneDrive</span><span>Design concept · sample data</span></div>`;
document.querySelectorAll('[data-direction]').forEach(b=>{if(b.tagName==='BUTTON')b.setAttribute('aria-pressed',String(b.dataset.direction===state.direction));});
document.querySelector('#theme-toggle').innerHTML=icon(state.theme==='light'?'moon':'sun');
document.querySelector('#theme-toggle').setAttribute('aria-label','Switch to '+(state.theme==='light'?'dark':'light')+' theme');
document.querySelector('#platform-toggle').textContent=state.platform==='windows'?'Windows':'macOS';
document.querySelector('#state-picker').value=state.scenario;
document.querySelector('#concept-name').textContent=descriptions[state.direction][0];
document.querySelector('#concept-description').textContent=descriptions[state.direction][1];
}
let toastTimer;
function notify(text){state.toast=text;clearTimeout(toastTimer);render();const page=state.page;toastTimer=setTimeout(()=>{if(state.page===page){state.toast='';render();}},2700);}
function dialog(title,body,actions=button('Done','data-action="close-dialog"','','primary')){const d=document.querySelector('#sample-dialog');d.innerHTML=`<h2>${title}</h2>${body}<div class="actions">${actions}</div>`;d.showModal();}
function closeMenu(){const m=document.querySelector('#menu');if(m.matches(':popover-open'))m.hidePopover();document.querySelectorAll('[aria-expanded=true]').forEach(el=>el.setAttribute('aria-expanded','false'));}
function showMenu(trigger,key){
closeMenu();const [kind,id]=key.split(':');const m=document.querySelector('#menu');
if(kind==='mode'){const p=projects.find(p=>p.id===id);m.innerHTML=['full','history','excluded'].map(value=>button(`${modeLabel(value)}${p.mode===value?icon('check'):''}`,`data-mode="${value}" data-target="${id}" role="menuitemradio" aria-checked="${p.mode===value}"`)).join('');m.setAttribute('role','menu');}
else {const p=projects.find(p=>p.id===id);const path=p?'D: / '+p.folder:({history:'D: / Codex / .codex',workspaces:'D: / Codex / Sessions',cloud:'OneDrive / Spice Route'}[id]||'Projects / Atlas');m.innerHTML=`<div class="menu-path">${path}</div>${button('Choose another folder…',`data-folder-target="${id}" role="menuitem"`,'folder')}${button('Copy path',`data-copy-path="${esc(path)}" role="menuitem"`,'copy')}<div class="menu-note">Changing a path does not move files.</div>`;m.setAttribute('role','menu');}
trigger.setAttribute('aria-expanded','true');m.showPopover();const r=trigger.getBoundingClientRect();const mh=m.getBoundingClientRect().height;m.style.left=Math.min(Math.max(10,r.right-224),innerWidth-234)+'px';m.style.top=(r.bottom+mh+15>innerHeight?Math.max(10,r.top-mh-5):r.bottom+5)+'px';m.querySelector('button').focus();
}
function folderDialog(id){closeMenu();const p=projects.find(p=>p.id===id);dialog('Choose a local folder',`<p>This preview uses sample folders. The finished app will open the native folder picker.</p><div class="choice-list">${['D: / Code / '+(p?p.name:'Atlas'),'E: / Projects / '+(p?p.name:'Atlas')].map(path=>button(esc(path),`data-picked-folder="${esc(path)}" data-target="${id}"`,'folder')).join('')}</div>`,button('Cancel','data-action="close-dialog"'));}
document.addEventListener('click',async e=>{
const b=e.target.closest('button,[data-project]');if(!b)return;
if(b.dataset.direction){state.direction=b.dataset.direction;state.query='';state.toast='';render();return;}
if(b.dataset.page){state.page=b.dataset.page;state.toast='';state.query='';state.saved=false;render();return;}
if(b.dataset.project){state.selected=b.dataset.project;render();return;}
if(b.dataset.menu){showMenu(b,b.dataset.menu);return;}
if(b.dataset.mode){projects.find(p=>p.id===b.dataset.target).mode=b.dataset.mode;closeMenu();render();return;}
if(b.dataset.selectionTab){state.selectionTab=b.dataset.selectionTab;state.query='';render();return;}
if(b.dataset.tab){state.tab=b.dataset.tab;render();return;}
if(b.dataset.group){state.reviewGroup=b.dataset.group;render();return;}
if(b.dataset.choice){state.choices.chat=b.dataset.choice;render();return;}
if(b.dataset.settingsTab){state.settingsTab=b.dataset.settingsTab;render();return;}
if(b.dataset.folderTarget){folderDialog(b.dataset.folderTarget);return;}
if(b.dataset.pickedFolder){const p=projects.find(p=>p.id===b.dataset.target);if(p)p.folder=b.dataset.pickedFolder.replace(/^[A-Z]: \/ /,'');if(b.dataset.target==='mapping')state.choices.folder=true;document.querySelector('#sample-dialog').close();notify('Folder selected');return;}
if(b.dataset.copyPath){try{await navigator.clipboard.writeText(b.dataset.copyPath);closeMenu();notify('Path copied');}catch{closeMenu();dialog('Folder path',`<p style="user-select:all">${esc(b.dataset.copyPath)}</p>`);}return;}
const action=b.dataset.action;
if(action?.startsWith('review-')){state.reviewDirection=action.endsWith('pull')?'pull':'push';state.page='review';state.tab=state.scenario==='blocked'?'attention':'files';state.saved=false;state.query='';render();}
else if(action==='execute'){state.progress=true;render();}
else if(action==='complete'){state.progress=false;state.saved=true;if(state.scenario==='progress')state.scenario='ready';state.page='review';render();}
else if(action==='cancel-progress'){state.progress=false;state.scenario='ready';state.page='review';render();}
else if(action==='save-choices')notify('Choices saved');
else if(action==='save-settings')notify('Settings saved');
else if(action==='refresh')notify('Sample view refreshed');
else if(action==='close-dialog')document.querySelector('#sample-dialog').close();
else if(action==='map-folder')folderDialog('mapping');
else if(action==='defaults')dialog('Default for new projects','<p>New projects start with Chat history only in these examples. Existing projects keep their individual choices.</p>');
else if(action==='sort'){state.sortAscending=!state.sortAscending;render();}
else if(action==='diagnostics')dialog('Pull diagnostics','<p>Review the Codex folder, database compatibility, restored chat count, and project paths in one report.</p><div class="note-row">'+icon('check')+'<div><strong>Example: 39 chats restored</strong><p>This is sample data. It does not confirm visibility in your Codex app.</p></div></div>');
else if(action==='storage')dialog('Cloud storage','<p>684 MB stored in the sample sync folder. Retained handoffs are separate from local restore points.</p><p>Cleanup stays a separate, explicit action in the finished app.</p>');
else if(action==='handoff-details')dialog('Today, '+latestTime(),'<p>From MacBook Pro · 39 chats · 12 project listings</p><p>Sep 22 · '+latestCode()+'</p><p>'+(hasIncoming()?'This handoff has not been pulled on Work PC.':'Received and verified on Work PC at 9:47 AM.')+'</p>');
else if(action==='restore-point')dialog('Review restore point','<p>The finished app will compare this restore point with your local data before changing any files.</p>');
else if(action==='copy-id'){try{await navigator.clipboard.writeText('20260922T102400-8C31');notify('Handoff ID copied');}catch{dialog('Handoff ID','<p style="user-select:all">20260922T102400-8C31</p>');}}
else if(action==='navigation-note')notify('Navigation stays expanded in these concepts');
});
document.addEventListener('input',e=>{if(e.target.id==='search-field'){const position=e.target.selectionStart;state.query=e.target.value;render();const input=document.querySelector('#search-field');input.focus();input.setSelectionRange(position,position);}});
document.addEventListener('change',e=>{if(e.target.id==='state-picker'){state.scenario=e.target.value;state.progress=false;state.saved=false;if(state.page==='review')state.tab=state.scenario==='blocked'?'attention':'files';render();}else if(e.target.id==='appearance'){state.theme=e.target.value==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):e.target.value;render();}else if(e.target.dataset.projectChat){projectChats.find(c=>c.id===e.target.dataset.projectChat).included=e.target.checked;render();}else if(e.target.dataset.chat){chats.find(c=>c.id===e.target.dataset.chat).included=e.target.checked;render();}});
document.querySelector('#theme-toggle').addEventListener('click',()=>{state.theme=state.theme==='light'?'dark':'light';render();});
document.querySelector('#platform-toggle').addEventListener('click',()=>{state.platform=state.platform==='windows'?'mac':'windows';render();});
document.querySelector('#menu').addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const items=[...e.currentTarget.querySelectorAll('button')];let n=items.indexOf(document.activeElement);n=e.key==='Home'?0:e.key==='End'?items.length-1:(n+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items[n].focus();}});
document.querySelector('#menu').addEventListener('toggle',e=>{if(e.newState==='closed')document.querySelectorAll('[aria-expanded=true]').forEach(el=>el.setAttribute('aria-expanded','false'));});
document.addEventListener('keydown',e=>{if(e.target.closest('[role=tablist]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const tabs=[...e.target.closest('[role=tablist]').querySelectorAll('button')];const i=(tabs.indexOf(e.target)+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;const tabId=tabs[i].dataset.tab,selectionId=tabs[i].dataset.selectionTab;tabs[i].click();document.querySelector(tabId?`[data-tab="${tabId}"]`:`[data-selection-tab="${selectionId}"]`).focus();}});
window.prototypeState=state;
window.renderPrototype=render;
render();
